class Solution {
public:
    int goodSubtreeSum(vector<int>& vals, vector<int>& par) {
        const int MOD=1000000007, M=1024;
        int n=vals.size();
        vector<vector<int>> child(n);
        for(int i=1;i<n;++i) child[par[i]].push_back(i);
        vector<int> order(1,0);
        for(int i=0;i<(int)order.size();++i)
            for(int v:child[order[i]]) order.push_back(v);
        vector<vector<long long>> dp(n,vector<long long>(M,-1));
        long long answer=0;
        for(int ii=n-1;ii>=0;--ii) {
            int u=order[ii],mask=0,x=vals[u];
            bool valid=true;
            while(x>0) {
                int d=x%10;
                if(mask&(1<<d)) valid=false;
                mask|=1<<d; x/=10;
            }
            dp[u][0]=0;
            if(valid) dp[u][mask]=vals[u];
            for(int v:child[u]) {
                vector<long long> next(M,-1);
                for(int a=0;a<M;++a) if(dp[u][a]>=0) {
                    int freeMask=(M-1)^a;
                    for(int b=freeMask;;b=(b-1)&freeMask) {
                        if(dp[v][b]>=0)
                            next[a|b]=max(next[a|b],dp[u][a]+dp[v][b]);
                        if(b==0) break;
                    }
                }
                dp[u].swap(next);
                vector<long long>().swap(dp[v]);
            }
            answer=(answer+*max_element(dp[u].begin(),dp[u].end()))%MOD;
        }
        return (int)answer;
    }
};
